<?php require 'config/bootstrap.php'; require_login(); $id=(int)($_GET['id']??0); $c=own_contract($id); $pdo=db();
function rows($q,$id){ global $pdo; $s=$pdo->prepare($q);$s->execute([$id]);return $s->fetchAll(); }
$f=rows('SELECT * FROM risk_findings WHERE contract_id=? ORDER BY FIELD(level,"high","medium","low")',$id); $o=rows("SELECT * FROM obligations WHERE contract_id=? ORDER BY due_date IS NULL,due_date",$id); $p=rows('SELECT * FROM payments WHERE contract_id=? ORDER BY due_date',$id); $n=rows('SELECT n.body,n.created_at,u.name FROM review_notes n JOIN users u ON u.id=n.user_id WHERE contract_id=?',$id);
$tot='0.00';$paid='0.00'; foreach($p as $x){$tot=bcadd($tot,$x['expected_amount'],2);$paid=bcadd($paid,$x['paid_amount']??'0',2);} log_act('report_viewed',$id); ?>
<!doctype html><html lang="en"><head><meta charset="utf-8"><title>Report - <?=e($c['title'])?></title><style>body{font-family:Arial,sans-serif;color:#111;max-width:820px;margin:2rem auto;padding:0 1rem}h1,h2{margin:.8rem 0 .3rem}table{border-collapse:collapse;width:100%}td,th{border:1px solid #bbb;padding:4px 6px;font-size:13px;text-align:left}pre{white-space:pre-wrap;background:#f3f3f3;padding:6px;font-size:12px}.np{margin-bottom:1rem}@media print{.np{display:none}}</style></head><body>
<div class="np"><button onclick="print()">Print / Save as PDF</button> <a href="contract.php?id=<?=$id?>">Back</a></div>
<h1><?=e($c['title'])?></h1><p><?=e($c['contract_type'])?> · <?=e($c['parties'])?> · <?=e($c['effective_date']?:'?')?> to <?=e($c['expiry_date']?:'?')?> · Status: <?=e($c['status'])?> · Heuristic risk: <?=e($c['risk_level'])?></p>
<h2>Risk findings (keyword heuristic)</h2><?php if(!$f):?><p>None recorded.</p><?php endif; foreach($f as $x):?><p><b><?=e(strtoupper($x['level']))?></b> <?=e($x['pillar'])?> [<?=e($x['review_status'])?>]: <?=e($x['explanation'])?></p><pre><?=e($x['evidence'])?></pre><?php endforeach;?>
<h2>Confirmed obligations</h2><table><tr><th>Description</th><th>Party</th><th>Due</th><th>Status</th></tr><?php foreach($o as $x):?><tr><td><?=e($x['description'])?></td><td><?=e($x['responsible_party'])?></td><td><?=e($x['due_date']?:'—')?></td><td><?=e($x['status'])?></td></tr><?php endforeach;?></table>
<h2>Payments</h2><table><tr><th>Due</th><th>Expected</th><th>Paid</th><th>Status</th></tr><?php foreach($p as $x):?><tr><td><?=e($x['due_date'])?></td><td><?=e($x['currency'].' '.$x['expected_amount'])?></td><td><?=e($x['paid_amount']??'—')?></td><td><?=e($x['status'])?></td></tr><?php endforeach;?></table><p>Expected total (mixed currencies not converted): <?=e($tot)?> · Recorded paid: <?=e($paid)?></p>
<h2>Review notes</h2><?php foreach($n as $x):?><p><?=nl2br(e($x['body']))?> <small>— <?=e($x['name'])?>, <?=e($x['created_at'])?></small></p><?php endforeach;?>
<p><small>Generated <?=date('Y-m-d H:i')?>. Informational only; not legal advice.</small></p></body></html>
